-- GENERADO por service/scripts/generar_sql_ayuda.py a partir de
-- retroalimentacion/ayuda-preguntas.md — no editar a mano.
--
-- Ayuda de las 50 preguntas del formulario público (definición y preguntas
-- guía). Contenido de trabajo, pendiente de revisión del Dr. Sergio.
-- Requiere la migración 20261117000001.

begin;

update nom036.item set ayuda_definicion = $txt$**Manejo manual de cargas:** toda actividad en la que una o varias personas levantan, bajan, empujan, jalan, transportan o estiban materiales con su fuerza física, con o sin equipo auxiliar. La norma considera carga todo lo que pese 3 kg o más.$txt$, ayuda_preguntas_guia = array[$txt$¿En qué áreas o puestos se mueven a mano cargas de 3 kg o más?$txt$, $txt$¿La lista incluye también las tareas de empujar, jalar y estibar, no solo las de levantar?$txt$, $txt$¿Está por escrito y alguien la mantiene al día?$txt$]::text[]
  where numero = 1 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Características de la carga:** la norma pide conocer, para cada actividad, las dimensiones, el agarre, la forma, el peso y la estabilidad de lo que se maneja.$txt$, ayuda_preguntas_guia = array[$txt$¿Se ha pesado lo que se maneja en cada estación, o solo se calcula a ojo?$txt$, $txt$¿Se sabe cuál es la carga más pesada de cada estación?$txt$, $txt$¿El dato está registrado?$txt$]::text[]
  where numero = 2 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Áreas de tránsito y de trabajo:** la norma pide mantenerlas libres de obstáculos y conservar el orden y la limpieza donde se manejan cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay lugares donde haya que esquivar objetos con una carga en las manos?$txt$, $txt$¿El espacio permite girar y acomodar la carga sin posturas forzadas?$txt$, $txt$¿El orden se mantiene todos los días o solo de vez en cuando?$txt$]::text[]
  where numero = 3 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Estimación simple del nivel de riesgo (evaluación rápida):** primera valoración de cómo se manejan las cargas, para saber qué tan expuesto está el personal. Se hace con el Apéndice I de la norma (levantar, bajar o transportar) o con el Apéndice II (empujar o jalar).$txt$, ayuda_preguntas_guia = array[$txt$¿Se ha aplicado el Apéndice I o el II a alguna tarea?$txt$, $txt$¿Se aplicó a todas las tareas con manejo de cargas, o solo a algunas?$txt$, $txt$¿Los resultados están documentados?$txt$]::text[]
  where numero = 4 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Frecuencia:** cuántas veces se levanta o traslada una carga en un periodo, por ejemplo por minuto o por hora. La norma pide considerarla al identificar las actividades con manejo manual de cargas, junto con su duración.$txt$, ayuda_preguntas_guia = array[$txt$¿Se sabe cuántas veces por hora se levanta o traslada carga en cada tarea?$txt$, $txt$¿Ese dato se registró o es un cálculo de memoria?$txt$, $txt$¿Se registra también cuánto dura la actividad?$txt$]::text[]
  where numero = 5 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Masa máxima por edad y género (Tabla 1 de la norma):** menores de 18 años, 7 kg; mujeres de 18 a 45 años, 20 kg; hombres de 18 a 45 años, 25 kg; mayores de 45 años, 15 kg las mujeres y 20 kg los hombres, salvo que un médico avale más.$txt$, ayuda_preguntas_guia = array[$txt$¿Se conoce la edad y el género de quienes levantan o bajan cargas?$txt$, $txt$¿Alguna carga supera el límite que le corresponde a quien la maneja?$txt$, $txt$¿Esta revisión se hizo por escrito?$txt$]::text[]
  where numero = 6 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Informe del análisis:** la norma pide que el análisis de los factores de riesgo conste en un informe que señale, entre otras cosas, qué actividades del centro de trabajo implican manejo manual de cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay un documento o plano que indique qué puestos manejan cargas?$txt$, $txt$¿Corresponde a los puestos que existen hoy?$txt$, $txt$¿Se puede consultar cuando se necesita?$txt$]::text[]
  where numero = 7 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Medidas de control técnicas:** cambios físicos para reducir el esfuerzo, como acondicionar o redistribuir instalaciones, procesos, maquinaria y equipos; por ejemplo, acercar los materiales al lugar donde se usan.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay materiales que se trasladan lejos o varias veces sin necesidad?$txt$, $txt$¿Se ha movido algo de lugar para evitar agacharse, girar o estirarse con carga?$txt$, $txt$¿Esos cambios se basaron en un análisis?$txt$]::text[]
  where numero = 8 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Período de descanso:** tiempo que se otorga después de una actividad, o entre grupos de actividades, de manejo manual de cargas. La norma lo incluye entre las medidas administrativas para proteger al personal expuesto.$txt$, ayuda_preguntas_guia = array[$txt$¿Las tareas repetitivas con cargas tienen pausas definidas?$txt$, $txt$¿Las pausas están programadas o dependen de cada persona?$txt$, $txt$¿Se respetan en la práctica?$txt$]::text[]
  where numero = 9 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Masa acumulada:** el total de kilos que una persona transporta a mano durante su jornada. La norma fija un máximo de 10,000 kg por jornada de 8 horas para distancias menores a 10 m, o de 6,000 kg para distancias de hasta 20 m.$txt$, ayuda_preguntas_guia = array[$txt$¿Se sabe cuántos kilos mueve cada trabajador en un turno?$txt$, $txt$¿Alguna persona se acerca a esos límites?$txt$, $txt$¿Ese total se controla o se registra?$txt$]::text[]
  where numero = 10 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Equipos auxiliares:** vehículos de una o más ruedas, sin motor, que sirven de apoyo para mover material a distancias cortas y que el trabajador empuja o sostiene en parte; por ejemplo, carretillas, diablos y patines.$txt$, ayuda_preguntas_guia = array[$txt$¿Los puestos que mueven cargas tienen equipo auxiliar a la mano?$txt$, $txt$¿El personal lo usa de verdad, o solo existe?$txt$, $txt$¿Hay cargas pesadas que se siguen moviendo a mano?$txt$]::text[]
  where numero = 1 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Estabilidad de la carga:** que la carga no se mueva, se ladee ni se caiga durante el traslado. La norma pide asegurarla al empujar o jalar cargas, con o sin equipo auxiliar.$txt$, ayuda_preguntas_guia = array[$txt$¿Se revisa que la carga esté bien acomodada y sujeta antes de moverla?$txt$, $txt$¿Ha habido cargas que se caen del equipo durante el traslado?$txt$, $txt$¿Hay una forma establecida de hacer esa revisión?$txt$]::text[]
  where numero = 2 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Capacidad máxima de carga (capacidad nominal):** el peso máximo que el fabricante indica para un equipo auxiliar. La norma pide verificar que la carga no la exceda.$txt$, ayuda_preguntas_guia = array[$txt$¿Se sabe cuánto peso soporta cada diablo, patín o carretilla?$txt$, $txt$¿Esa capacidad está marcada en el equipo o registrada?$txt$, $txt$¿Se verifica que no se cargue de más?$txt$]::text[]
  where numero = 3 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Superficie de rodamiento:** el piso por el que circulan las ruedas del equipo auxiliar. La norma pide comprobar que esté en buenas condiciones, evitar pisos ranurados, deteriorados o resbalosos y retirar los obstáculos.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay baches, desniveles, grietas o rejillas en las rutas de traslado?$txt$, $txt$¿Los pisos suelen estar limpios y secos?$txt$, $txt$¿Se revisan antes de mover cargas?$txt$]::text[]
  where numero = 4 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Espacio de maniobra:** el lugar necesario para girar o maniobrar con la carga. La norma pide revisar que corresponda a las dimensiones de la carga, en especial en pasillos angostos.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay pasillos donde no se puede girar con el equipo cargado?$txt$, $txt$¿Peatones y cargas comparten el pasillo de forma segura?$txt$, $txt$¿Los pasillos se revisan de forma periódica?$txt$]::text[]
  where numero = 5 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Rampas y pendientes:** la norma pide evitarlas en la trayectoria cuando sea posible y, si no, jalar el equipo con ruedas en el mismo sentido al subir y en sentido opuesto al bajar. La señalización ayuda a usarlas con seguridad.$txt$, ayuda_preguntas_guia = array[$txt$¿Las rampas y plataformas tienen señalización visible?$txt$, $txt$¿Hay carriles pintados o indicaciones del sentido de circulación?$txt$, $txt$¿La señalización está en buen estado?$txt$]::text[]
  where numero = 6 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Condiciones seguras de operación:** que el equipo auxiliar (ruedas, frenos, estructura y asas) funcione bien. La norma pide revisarlo antes de iniciar las actividades.$txt$, ayuda_preguntas_guia = array[$txt$¿Alguien revisa ruedas, frenos y estructura de los equipos?$txt$, $txt$¿Esa revisión tiene una frecuencia definida?$txt$, $txt$¿El equipo dañado se repara o se retira?$txt$]::text[]
  where numero = 7 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Distribución de la carga:** acomodar el peso de forma pareja en el equipo auxiliar, para que no se vuelque ni se ladee y sea más fácil de empujar o jalar. La norma pide asegurar la estabilidad de la carga durante el traslado.$txt$, ayuda_preguntas_guia = array[$txt$¿Lo más pesado se acomoda abajo y al centro?$txt$, $txt$¿El personal sabe cómo repartir la carga?$txt$, $txt$¿Ha habido volcaduras o cargas inestables?$txt$]::text[]
  where numero = 8 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Condiciones del ambiente:** factores del lugar, como el ruido, la temperatura o la iluminación, que pueden aumentar el esfuerzo del trabajador o generar una situación de peligro. La norma pide considerarlas en el procedimiento de seguridad.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay zonas con poca luz, mucho calor o mucho ruido en las rutas de traslado?$txt$, $txt$¿Esas zonas están identificadas por escrito?$txt$, $txt$¿Se tomaron medidas para ellas?$txt$]::text[]
  where numero = 9 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Masa acumulada:** el total de kilos que una persona transporta a mano durante su jornada. La norma fija un máximo de 10,000 kg por jornada de 8 horas para distancias menores a 10 m, o de 6,000 kg para distancias de hasta 20 m.$txt$, ayuda_preguntas_guia = array[$txt$¿Existe un límite de kilos por jornada para quien transporta materiales?$txt$, $txt$¿Se cuenta también lo que se mueve con equipo auxiliar?$txt$, $txt$¿Se verifica que se respete?$txt$]::text[]
  where numero = 10 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Capacitación y adiestramiento:** la norma pide capacitar al personal expuesto según sus tareas y con énfasis en la prevención: los efectos a la salud, cómo reconocer los riesgos, el contenido de la norma y la forma segura de trabajar.$txt$, ayuda_preguntas_guia = array[$txt$¿Todo el personal que maneja cargas recibió capacitación sobre cómo hacerlo de forma segura?$txt$, $txt$¿Fue específica para sus tareas o general?$txt$, $txt$¿El personal de nuevo ingreso la recibe antes de empezar?$txt$]::text[]
  where numero = 1 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Registro de la capacitación:** la norma pide que incluya el nombre y puesto de los trabajadores, la fecha, los temas impartidos y el nombre del instructor.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay una lista de quién se capacitó y cuándo?$txt$, $txt$¿Incluye los temas y al instructor?$txt$, $txt$¿Está al día?$txt$]::text[]
  where numero = 2 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Componentes de la capacitación:** la norma pide que la capacitación consista en instrucción teórica, entrenamiento práctico y evaluación de los conocimientos y habilidades adquiridos.$txt$, ayuda_preguntas_guia = array[$txt$¿La capacitación incluye práctica, no solo explicación?$txt$, $txt$¿Se evalúa lo aprendido?$txt$, $txt$¿Se hace así en todas las sesiones?$txt$]::text[]
  where numero = 3 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Empujar, jalar o arrastrar (tracción) cargas:** tareas en las que se mueve una carga con una fuerza horizontal, a mano o con equipo auxiliar. Al empujar, la fuerza se aleja del cuerpo; al jalar, se dirige hacia él.$txt$, ayuda_preguntas_guia = array[$txt$¿El personal de almacén sabe empujar y jalar sin forzar la espalda?$txt$, $txt$¿Se le ha enseñado a usar diablos, patines y carretillas en rampas?$txt$, $txt$¿Esa capacitación incluyó práctica?$txt$]::text[]
  where numero = 4 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Aptitud física:** la condición de salud que permite a una persona manejar cargas sin riesgo. La norma pide que esté avalada por un médico y que se apliquen exámenes médicos iniciales.$txt$, ayuda_preguntas_guia = array[$txt$¿Se hace un examen médico antes de asignar a alguien a tareas con cargas?$txt$, $txt$¿Ese examen evalúa específicamente el manejo de cargas?$txt$, $txt$¿Los resultados quedan registrados?$txt$]::text[]
  where numero = 5 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Vigilancia a la salud de los trabajadores:** seguimiento médico del personal expuesto. La norma pide exámenes según la actividad de cada trabajador, con seguimiento anual o antes si aparecen signos o síntomas de un posible trastorno musculoesquelético.$txt$, ayuda_preguntas_guia = array[$txt$¿El personal expuesto tiene revisión médica al menos una vez al año?$txt$, $txt$¿Se revisa antes si alguien reporta dolor o molestias?$txt$, $txt$¿La realiza un médico?$txt$]::text[]
  where numero = 6 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Restricción médica:** cuando el médico determina que una persona no tiene la aptitud física para cierta carga o que necesita un período de recuperación. La norma deja esa determinación al médico.$txt$, ayuda_preguntas_guia = array[$txt$¿Ha habido personal con restricción médica para cargar?$txt$, $txt$¿Se le asignó otra tarea compatible con su salud?$txt$, $txt$¿Hay una forma establecida de hacerlo?$txt$]::text[]
  where numero = 7 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Hábitos posturales:** formas de colocar y mover el cuerpo al trabajar, como doblar las rodillas al levantar, mantener la carga cerca del cuerpo y no girar el tronco con peso.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay campañas, carteles o pláticas sobre posturas al cargar?$txt$, $txt$¿Se repiten de forma periódica?$txt$, $txt$¿Llegan a todo el personal?$txt$]::text[]
  where numero = 8 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Reforzamiento de la capacitación:** repetir o actualizar la capacitación de forma periódica y, además, cuando se introducen herramientas o equipos nuevos, cambian las condiciones de trabajo o se detectan condiciones inseguras.$txt$, ayuda_preguntas_guia = array[$txt$¿Cuándo fue la última capacitación del personal expuesto?$txt$, $txt$¿Se repite cada año?$txt$, $txt$¿Se vuelve a dar cuando cambia el proceso o llega equipo nuevo?$txt$]::text[]
  where numero = 9 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Fatiga de trabajo:** la manifestación física o mental del sobreesfuerzo, que desaparece por completo con el descanso. Cuidar el bienestar del personal incluye prevenirla, junto con el estrés y la sobrecarga de trabajo.$txt$, ayuda_preguntas_guia = array[$txt$¿Se toma en cuenta el cansancio del personal al asignar tareas pesadas?$txt$, $txt$¿El personal puede reportar malestar o exceso de trabajo?$txt$, $txt$¿Se actúa cuando lo reporta?$txt$]::text[]
  where numero = 10 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Política interna:** documento de la empresa que declara su compromiso con la prevención de riesgos ergonómicos y fija reglas generales para lograrlo.$txt$, ayuda_preguntas_guia = array[$txt$¿Existe por escrito?$txt$, $txt$¿La respalda la dirección?$txt$, $txt$¿El personal la conoce?$txt$]::text[]
  where numero = 1 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Responsable del cumplimiento:** persona o área designada para dar seguimiento, dentro del centro de trabajo, a lo que pide la NOM-036-1-STPS-2018.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay una persona o un área a cargo de la norma?$txt$, $txt$¿Su designación es oficial?$txt$, $txt$¿Tiene tiempo y recursos para hacerlo?$txt$]::text[]
  where numero = 2 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Presupuesto para equipos auxiliares:** recursos asignados de forma planeada para comprar o renovar carretillas, diablos, patines y otros apoyos para mover cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay una partida para estos equipos?$txt$, $txt$¿Se planea cada año o solo se compra cuando algo falla?$txt$, $txt$¿Se usó en el último año?$txt$]::text[]
  where numero = 3 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Registros:** la norma pide llevar el registro de las medidas preventivas adoptadas y de los exámenes médicos practicados.$txt$, ayuda_preguntas_guia = array[$txt$¿Se guardan los diagnósticos, programas y acciones de ergonomía?$txt$, $txt$¿Están actualizados?$txt$, $txt$¿Se pueden consultar con facilidad?$txt$]::text[]
  where numero = 4 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Supervisión:** verificar que las actividades con cargas se hagan en condiciones seguras, con base en el procedimiento de seguridad que pide la norma.$txt$, ayuda_preguntas_guia = array[$txt$¿Alguien revisa en el área de trabajo que se apliquen las medidas?$txt$, $txt$¿Con qué frecuencia?$txt$, $txt$¿Hay un formato o criterio para hacerlo?$txt$]::text[]
  where numero = 5 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Unidad de verificación:** organismo acreditado y aprobado que revisa el grado de cumplimiento de la norma. Contratarla es opcional para el patrón; también puede hacerse una auditoría interna.$txt$, ayuda_preguntas_guia = array[$txt$¿Se ha revisado alguna vez el cumplimiento de la norma?$txt$, $txt$¿La revisión fue interna o externa?$txt$, $txt$¿Se atendieron sus hallazgos?$txt$]::text[]
  where numero = 6 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Informar al personal:** la norma pide informar a los trabajadores sobre las posibles alteraciones a la salud por el manejo manual de cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿El personal sabe qué es la NOM-036 y por qué importa?$txt$, $txt$¿Se usan carteles, pláticas o boletines?$txt$, $txt$¿Se hace de forma regular?$txt$]::text[]
  where numero = 7 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Disponibilidad del análisis:** la norma pide que el análisis de los factores de riesgo esté disponible para los trabajadores que manejan cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿El personal puede consultar los riesgos de su puesto?$txt$, $txt$¿La información está en un lugar y formato accesibles?$txt$, $txt$¿Se le avisa dónde encontrarla?$txt$]::text[]
  where numero = 8 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Diagnóstico de seguridad y salud en el trabajo:** identificación de las condiciones inseguras y de los factores de riesgo del centro de trabajo que exige la NOM-030-STPS-2009. La NOM-036 pide integrar ahí el análisis del riesgo por manejo de cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿El diagnóstico ergonómico forma parte del diagnóstico o programa de seguridad y salud?$txt$, $txt$¿Se actualizan juntos?$txt$, $txt$¿Las acciones de ergonomía aparecen en ese programa?$txt$]::text[]
  where numero = 9 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Cultura de prevención:** que la prevención de riesgos y la ergonomía formen parte de la forma habitual de trabajar, con la participación de la dirección y del personal.$txt$, ayuda_preguntas_guia = array[$txt$¿La dirección participa en las acciones de ergonomía?$txt$, $txt$¿El personal propone mejoras?$txt$, $txt$¿Hay actividades de prevención de forma continua?$txt$]::text[]
  where numero = 10 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Análisis de los factores de riesgo ergonómico:** según la norma, se integra por tres partes: identificar las actividades con manejo manual de cargas, estimar su nivel de riesgo y, cuando haga falta, hacer una evaluación específica.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay un diagnóstico centrado en el manejo manual de cargas?$txt$, $txt$¿Incluye la identificación de actividades y la estimación del riesgo?$txt$, $txt$¿Está por escrito?$txt$]::text[]
  where numero = 1 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Evaluación específica del nivel de riesgo:** valoración detallada con métodos científicamente validados, como la ecuación de NIOSH o el método de la norma ISO 11228-2 para empujar o jalar. Se aplica cuando la evaluación rápida no basta o persiste algún peligro.$txt$, ayuda_preguntas_guia = array[$txt$¿Se ha aplicado algún método formal de evaluación a algún puesto?$txt$, $txt$¿Lo aplicó una persona capacitada?$txt$, $txt$¿Los resultados se usaron para decidir medidas?$txt$]::text[]
  where numero = 2 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Medidas de control técnicas:** cambios en los procedimientos, instalaciones, procesos, maquinaria o equipos para reducir el esfuerzo, como redistribuir espacios o adecuar estaciones de trabajo.$txt$, ayuda_preguntas_guia = array[$txt$¿Se han hecho cambios físicos para reducir el esfuerzo?$txt$, $txt$¿Se basaron en el análisis de riesgo?$txt$, $txt$¿Se revisó si funcionaron?$txt$]::text[]
  where numero = 3 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Medidas de control administrativas:** cambios en la organización del trabajo, como limitar tiempos y frecuencias, programar descansos, diversificar actividades o rotar al personal.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay rotación de puestos o pausas programadas?$txt$, $txt$¿Están por escrito?$txt$, $txt$¿Se aplican en todos los turnos?$txt$]::text[]
  where numero = 4 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Programa de ergonomía:** documento que, según la norma, indica los puestos sujetos al programa, las medidas de control, las fechas de ejecución (no mayores a un año), el control de avances, el responsable y la evaluación posterior.$txt$, ayuda_preguntas_guia = array[$txt$¿Existe un programa de ergonomía por escrito?$txt$, $txt$¿Tiene responsables y fechas?$txt$, $txt$¿Se le da seguimiento?$txt$]::text[]
  where numero = 5 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Trastorno musculoesquelético laboral:** lesión o enfermedad de músculos, huesos, tendones o articulaciones causada por la exposición a factores de riesgo ergonómico en el trabajo.$txt$, ayuda_preguntas_guia = array[$txt$¿Se registran los casos de dolor o lesión relacionados con el manejo de cargas?$txt$, $txt$¿Se les da seguimiento médico?$txt$, $txt$¿Se revisan las tareas de quien presenta un caso?$txt$]::text[]
  where numero = 6 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Cuestionario Nórdico de Kuorinka:** cuestionario que la norma propone, como una opción, para detectar signos o síntomas de un posible trastorno musculoesquelético en el personal.$txt$, ayuda_preguntas_guia = array[$txt$¿Se ha aplicado algún cuestionario sobre molestias o dolor al personal?$txt$, $txt$¿A todo el personal expuesto?$txt$, $txt$¿Se analizaron las respuestas?$txt$]::text[]
  where numero = 7 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Mejora continua:** revisar de forma periódica los resultados de las acciones de ergonomía para ajustar lo que no funciona y mantener lo que sí.$txt$, ayuda_preguntas_guia = array[$txt$¿Se reportan los avances en ergonomía?$txt$, $txt$¿Con qué frecuencia?$txt$, $txt$¿Esos reportes llevan a nuevas acciones?$txt$]::text[]
  where numero = 8 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Síntomas musculoesqueléticos:** molestias como dolor, hormigueo, rigidez o pérdida de fuerza en espalda, cuello, hombros o extremidades. La norma pide que la capacitación incluya los efectos a la salud del manejo de cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿El personal sabe reconocer las primeras molestias?$txt$, $txt$¿Sabe a quién reportarlas?$txt$, $txt$¿Esto se incluye en la capacitación?$txt$]::text[]
  where numero = 9 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Medidas de control en el programa:** la norma pide que el programa de ergonomía indique qué medidas de control técnicas y administrativas deberán adoptarse.$txt$, ayuda_preguntas_guia = array[$txt$¿El programa dice qué medidas se aplicarán y en qué puestos?$txt$, $txt$¿Están descritas con claridad para quien las aplica?$txt$, $txt$¿Se actualizan cuando cambian las condiciones?$txt$]::text[]
  where numero = 10 and criterio_id = (select id from nom036.criterio where numero = 5);

commit;
